wwv_flow_imp_page.create_page(
 p_id=>1
,p_name=>'Home'
,p_alias=>'HOME'
,p_step_title=>'attandance'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code_onload=>wwv_flow_string.join(wwv_flow_t_varchar2(
'document.querySelectorAll(''.value'').forEach(el => {',
'    let countTo = parseInt(el.textContent || 0);',
'    let count = 0;',
'    let increment = Math.ceil(countTo / 100);',
'    let interval = setInterval(() => {',
'        count += increment;',
'        if(count >= countTo){',
'            count = countTo;',
'            clearInterval(interval);',
'        }',
'        el.textContent = count;',
'    }, 20);',
'});',
''))
,p_inline_css=>wwv_flow_string.join(wwv_flow_t_varchar2(
'@import url("https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.0.0/css/all.min.css");',
'',
'/* Background */',
'body {',
'    font-family: ''Poppins'', sans-serif;',
'    background: #f2f4f7;',
'    margin: 0;',
'    padding: 0;',
'}',
'',
'/* Grid Layout */',
'.glass-grid {',
'    display: grid;',
'    grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));',
'    gap: 25px;',
'    padding: 40px;',
'}',
'',
'/* Clean Sharp Industry Card */',
'.glass-card {',
'    background: #ffffff;',
'    border-radius: 18px;',
'    padding: 25px 20px;',
'    text-align: center;',
'',
'    /* Sharp shadow, no blur */',
'    box-shadow: ',
'        0 5px 15px rgba(0, 0, 0, 0.12),',
'        0 2px 4px rgba(0,0,0,0.08);',
'',
'    border: 1px solid #e6e6e6;',
'',
'    transition: 0.25s ease-in-out;',
'}',
'',
'/* Hover effect - clean pop */',
'.glass-card:hover {',
'    transform: translateY(-8px);',
'    box-shadow: ',
'        0 10px 25px rgba(0, 0, 0, 0.18),',
'        0 4px 8px rgba(0,0,0,0.1);',
'}',
'',
'/* Icons */',
'.icon {',
'    font-size: 48px;',
'    margin-bottom: 12px;',
'}',
'',
'/* Title */',
'.title {',
'    font-size: 20px;',
'    font-weight: 600;',
'    color: #444;',
'    margin-bottom: 6px;',
'}',
'',
'/* Number */',
'.value {',
'    font-size: 42px;',
'    font-weight: 700;',
'    color: #111;',
'}',
'',
'/* Color Themes (Sharp, Solid Colors) */',
'',
'.blue-card .icon,',
'.blue-card .title,',
'.blue-card .value { color: #1e6bff; }',
'',
'.green-card .icon,',
'.green-card .title,',
'.green-card .value { color: #05a85c; }',
'',
'.purple-card .icon,',
'.purple-card .title,',
'.purple-card .value { color: #8f00d4; }',
'',
'.teal-card .icon,',
'.teal-card .title,',
'.teal-card .value { color: #009e9e; }',
'',
'.pink-card .icon,',
'.pink-card .title,',
'.pink-card .value { color: #ff3b8d; }',
'',
'.orange-card .icon,',
'.orange-card .title,',
'.orange-card .value { color: #ff7b00; }',
'',
'//for heading',
'.emp-heading {',
'  display: flex;',
'  align-items: center;',
'  gap: 12px;',
'  color: #1f4bd8;          /* Primary blue */',
'  font-weight: 700;',
'  letter-spacing: .3px;',
'  margin-bottom: 16px;',
'}',
'',
'.emp-icon {',
'  background: #e8edff;     /* Soft blue background */',
'  color: #1f4bd8;',
'  border-radius: 50%;',
'  padding: 10px;',
'  font-size: 18px;',
'}',
'',
''))
,p_page_template_options=>'#DEFAULT#'
,p_protection_level=>'C'
,p_page_component_map=>'13'
);
