wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(204662360574059660)
,p_plug_name=>'Employee Profile'
,p_region_template_options=>'#DEFAULT#:t-Region--removeHeader js-removeLandmark:t-Region--noUI:t-Region--scrollBody'
,p_plug_template=>4072358936313175081
,p_plug_display_sequence=>10
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    e.EMP_CODE,',
'    e.EMP_NAME,',
'    e.EMP_FNAME,',
'    e.IDC_NO,',
'    e.EMP_ADDRESS,',
'    e.PHONE_NO,',
'',
'    get_department@payroll(e.DEPT_ID) AS DEPARTMENT,',
'    get_designation@payroll(e.DESG_ID) AS DESIGNATION,',
'    get_cost_center@payroll(e.COST_ID) AS COST_CENTER,',
'',
'    (',
'        SELECT UPPER(l.LOC_NAME)',
'        FROM COMPANY_LOCATION@payroll l',
'        WHERE l.LOC_ID = e.LOC_ID',
'    ) AS LOCATION,',
'',
'    e.NTN_NO,',
'    e.GROSS_PAY,',
'    e.START_PAY,',
'    e.HIRE_DATE,',
'    e.LAST_UP_DATE,',
'    e.QUIT_STATUS,',
'    e.QUIT_DATE,',
'    e.BANK_AC_NO,',
'    e.EMP_TYPE,',
'    e.EOB_CARD_ID,',
'    e.SS_ID,',
'    e.BLOD_GROUP,',
'    e.QUALIF,',
'    e.CASTE_EMP,',
'    e.DOB_DATE,',
'    e.RELIGION,',
'    e.CASH_BANK,',
'    e.SHIFT_ID,',
'    e.CONVANCE,',
'    e.CONV_TYPE,',
'    e.CONV_NO,',
'    e.HOD,',
'    e.FAMILY_NO,',
'    e.NEXT_KIN,',
'    e.EMG_PH,',
'    e.REST,',
'    e.OT,',
'    e.EOBI,',
'    e.SS,',
'    e.GROUP_INSU,',
'    e.REPLACEMENT_CODE,',
'    e.GERDER,',
'    e.CITY,',
'    e.SHIFT,',
'    e.CL,',
'    e.SL,',
'    e.AL,',
'    e.FUEL,',
'    e.TOLL_TAX,',
'    e.MAINTINANCE,',
'    e.IDC_E_DATE,',
'    e.ROOM_NUM,',
'    e.QUIT_DETAIL,',
'    e.UNAME,',
'    e.TERMINAL,',
'    e.SYS_DT,',
'    e.LU_UNAME,',
'    e.LU_TERMINAL,',
'    e.LU_SYS_DT,',
'    e.SS_SALARY,',
'    e.FIXED_COST,',
'    e.BANK_SALARY,',
'    e.BANK_NAME,',
'    e.REMARKS,',
'    e.CNIC_ISSUE_DATE,',
'    e.MOTHER_NAME,',
'    e.DUTY_HRS,',
'    e.COVID,',
'    e.DISABILITY,',
'    e.MARITAL_STATUS,',
'    e.GRADE,',
'    e.EOBI_START_DT,',
'    e.SS_START_DT,',
'    e.TRIAL,',
'    e.TRIAL_END_DT,',
'    e.CREATION_DATE,',
'    e.REF_CONT,',
'    e.PROFILE_LOCK,',
'    e.LOCK_DATE,',
'    e.LOCK_BY',
'',
'FROM EMPLOYEE@PAYROLL e',
'',
'',
''))
,p_is_editable=>true
,p_edit_operations=>'i:u:d'
,p_lost_update_check_type=>'VALUES'
,p_plug_source_type=>'NATIVE_FORM'
,p_plug_header=>'<h1 class="employee-profile-title">Employee Profile</h1>'
);
